package com.android.messaging.ui;
import android.content.Context;import android.graphics.Bitmap;import android.graphics.Canvas;import android.graphics.Color;import android.graphics.Paint;import android.graphics.Typeface;import android.util.AttributeSet;import android.support.v7.widget.AppCompatImageView;import com.android.messaging.util.AppPrefs;
public class ContactIconView extends AppCompatImageView {public ContactIconView(Context c){super(c);}public ContactIconView(Context c,AttributeSet a){super(c,a);}public ContactIconView(Context c,AttributeSet a,int s){super(c,a,s);}public void bind(String name,String address){int size=Math.max(1,getLayoutParams()!=null&&getLayoutParams().width>0?getLayoutParams().width:Math.round(56*getResources().getDisplayMetrics().density));Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);int color=AppPrefs.conversationColor(getContext(),address);p.setColor(color);cv.drawCircle(size/2f,size/2f,size/2f,p);String n=name==null||name.trim().isEmpty()?"?":name.trim().substring(0,1).toUpperCase();p.setColor(luma(color)>.6?Color.BLACK:Color.WHITE);p.setTextSize(size*.46f);p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.NORMAL));p.setTextAlign(Paint.Align.CENTER);Paint.FontMetrics fm=p.getFontMetrics();cv.drawText(n,size/2f,size/2f-(fm.ascent+fm.descent)/2f,p);setImageBitmap(b);setClipToOutline(true);}private static double luma(int c){return(.299*Color.red(c)+.587*Color.green(c)+.114*Color.blue(c))/255d;}}
